changeSet.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.table_constraints
              WHERE constraint_name = 'fk_lab_grown_diamonds_mirror_product') THEN
        ALTER TABLE lab_grown_diamonds DROP CONSTRAINT fk_lab_grown_diamonds_mirror_product;
    END IF;
END $$;

DELETE FROM vendor_products
WHERE id NOT IN (
    SELECT vp.id
    FROM vendor_products vp
    INNER JOIN products p ON vp.product_id = p.id
);
